  "claims": [
    {
      "claim": "The query is a permanently charged quaternary ammonium tropane ester. The most transferable reference context, umeclidinium, is also a quaternary ammonium antimuscarinic and has negligible oral bioavailability, with systemic availability ≤12% from oral and inhaled routes.",
      "card_ids": ["C01", "C05", "C10", "C17"]
    },
    {
      "claim": "L3 oral-exposure records for other quaternary ammonium antimuscarinics show very low plasma concentrations after oral dosing (glycopyrronium 2 mg Cmax 318 pg/mL; trospium 60 mg XR Cmax ~1.5 ng/mL), consistent with poor oral absorption. These records lack IV comparators and are not direct F measurements, but they support the low prediction; repeated trospium records are not independent votes.",
      "card_ids": ["C32", "C37", "C38", "C41", "C42"]
    },
    {
      "claim": "No query-specific direct oral bioavailability measurement exists, and no class-level evidence supports F ≥ 20%; the low prediction rests on transferable direct low-F evidence and coherent absorption behavior, not on generic descriptor liabilities alone.",
      "card_ids": ["C01", "C05", "C10", "C17", "C32", "C37"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C32", "C37", "C38", "C41", "C42"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific permeability or absorption data are available; transfer from umeclidinium/trospium/glycopyrronium is structural/class analogy.",
    "L3 oral-exposure records lack IV comparators and therefore cannot directly quantify absolute oral bioavailability.",
    "Query formulation and prandial state are unspecified.",
    "The query's epoxide and ester may introduce metabolic lability, but no direct data are supplied."
  ],
  "decision_summary": "The query is a permanently charged quaternary ammonium tropane ester. Transferable direct evidence from umeclidinium (negligible oral bioavailability, ≤12% systemic availability) and L3 oral-exposure records for trospium/glycopyrronium (very low plasma Cmax after oral dosing) coherently support F < 20%. No query-specific or class-level evidence supports F ≥ 20%. Prediction remains low; confidence high."
}

